pub fn with_tab_group<R>(&mut self, index: Option<isize>, f: impl FnOnce(&mut Self) -> R) -> R {
    if let Some(index) = index {
        self.next_frame.tab_stops.begin_group(index);
        let result = f(self);
        self.next_frame.tab_stops.end_group();
        result
    } else {
        f(self)
    }
}

